            <FormControl size="small"><InputLabel>Pay Period</InputLabel><Select value={period} label="Pay Period" onChange={changeFilter(setPeriod)}><MenuItem value="">All Pay Periods</MenuItem>{payPeriods.map(([key, item]) => <MenuItem key={key} value={key}>{formatPeriod(item.payPeriodStart, item.payPeriodEnd)}</MenuItem>)}</Select></FormControl>
            <FormControl size="small"><InputLabel>Status</InputLabel><Select value={status} label="Status" onChange={changeFilter(setStatus)}><MenuItem value="">All Statuses</MenuItem>{statuses.map((value) => <MenuItem key={value} value={value}>{displayStatus(value)}</MenuItem>)}</Select></FormControl>
